const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Dublin city center coordinates
  const dublin = ee.Geometry.Point(-6.2603, 53.3498).buffer(20000); // 20 km buffer around Dublin city center

  const date1_start = '1984-11-01';
  const date1_end = '1984-11-30';
  const date2_start = '2022-11-01';
  const date2_end = '2022-11-30';

  const scale = 1000; // Resolution for analysis in meters to avoid timeout
  const pixelAreaSqM = 30 * 30; // Landsat pixel area in square meters

  // Function to mask clouds for Landsat 5 SR
  const maskCloudsL5 = function(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud and cloud shadow, respectively.
    const cloudBitmask = (1 << 3);
    const cloudShadowBitmask = (1 << 5);
    // Both flags should be set to 0, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitmask).eq(0)
                 .and(qa.bitwiseAnd(cloudShadowBitmask).eq(0));
    return image.updateMask(mask).divide(10000)
                .select(['B4', 'B5', 'B7'], ['NIR', 'SWIR1', 'SWIR2']) // Standardize band names
                .copyProperties(image, ['system:time_start']);
  };

  // Function to mask clouds for Landsat 8/9 SR
  const maskCloudsL8_9 = function(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3, 4, and 5 are cloud shadow, cloud, and cirrus, respectively.
    const cloudShadowBitmask = (1 << 3);
    const cloudBitmask = (1 << 4);
    const cirrusBitmask = (1 << 5);
    // Both flags should be set to 0, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitmask).eq(0)
                 .and(qa.bitwiseAnd(cloudBitmask).eq(0))
                 .and(qa.bitwiseAnd(cirrusBitmask).eq(0));
    return image.updateMask(mask).divide(10000)
                .select(['B5', 'B6', 'B7'], ['NIR', 'SWIR1', 'SWIR2']) // Standardize band names
                .copyProperties(image, ['system:time_start']);
  };

  // Function to calculate NDBI and classify built-up
  const calculateBuiltUp = function(image) {
    // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
    const ndbi = image.normalizedDifference(['SWIR1', 'NIR']).rename('NDBI');
    // Threshold for built-up area (can be adjusted based on local conditions)
    const builtUp = ndbi.gt(0.15).rename('built_up');
    return builtUp;
  };

  // 2. Data Acquisition & Check
  let col1 = ee.ImageCollection('LANDSAT/LT05/C02/SR')
    .filterBounds(dublin)
    .filterDate(date1_start, date1_end)
    .map(maskCloudsL5);

  let col2 = ee.ImageCollection('LANDSAT/LC08/C02/SR')
    .merge(ee.ImageCollection('LANDSAT/LC09/C02/SR')) // Merge L8 and L9 for 2022
    .filterBounds(dublin)
    .filterDate(date2_start, date2_end)
    .map(maskCloudsL8_9);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`1984 Images: ${size1}, 2022 Images: ${size2}`);
    console.log("No images found for one or both periods.");
    console.log("C1");
    return;
  }

  // Get median images
  const img1 = col1.median();
  const img2 = col2.median();

  // 3. Processing: Calculate built-up area for each period
  const builtUp1 = calculateBuiltUp(img1);
  const builtUp2 = calculateBuiltUp(img2);

  // Validate valid pixels after masking and classification
  const count1 = await builtUp1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dublin,
    scale: scale,
    maxPixels: 1e9
  }).get('built_up').getInfo();

  const totalPixels1 = await builtUp1.mask(builtUp1).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: scale,
    maxPixels: 1e9
  }).get('built_up').getInfo();

  const count2 = await builtUp2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: dublin,
    scale: scale,
    maxPixels: 1e9
  }).get('built_up').getInfo();

  const totalPixels2 = await builtUp2.mask(builtUp2).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: scale,
    maxPixels: 1e9
  }).get('built_up').getInfo();


  if (totalPixels1 === 0 || totalPixels2 === 0) {
    console.log(`1984 Images: ${size1} (Valid Pixels: ${totalPixels1})`);
    console.log(`2022 Images: ${size2} (Valid Pixels: ${totalPixels2})`);
    console.log("No valid pixels remaining after cloud masking for one or both periods.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  // Convert built-up pixel count to area in square kilometers
  const area1_sqkm = (count1 * pixelAreaSqM) / 1e6;
  const area2_sqkm = (count2 * pixelAreaSqM) / 1e6;

  // 5. Validation & Final Answer
  if (area1_sqkm === null || area2_sqkm === null || isNaN(area1_sqkm) || isNaN(area2_sqkm)) {
    console.log(`1984 Images: ${size1} (Val: ${area1_sqkm}, Pixels: ${totalPixels1})`);
    console.log(`2022 Images: ${size2} (Val: ${area2_sqkm}, Pixels: ${totalPixels2})`);
    console.log("Calculation resulted in null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`1984 Images: ${size1} (Valid Pixels: ${totalPixels1})`);
  console.log(`2022 Images: ${size2} (Valid Pixels: ${totalPixels2})`);
  console.log(`Built-up area (Nov 1984): ${area1_sqkm.toFixed(2)} sq km`);
  console.log(`Built-up area (Nov 2022): ${area2_sqkm.toFixed(2)} sq km`);

  if (area2_sqkm > area1_sqkm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
